function fft_hrw_decim_cb(path,idx,first){if(first)return;fft.hrw_decim_i=+idx;w3_select_value(path,idx);fft.hrw.init=false;fft_clear();}
function fft_hrw_zoom_cb(path,idx,first){if(first)return;fft.hrw_zoom_i=+idx;w3_select_value(path,idx);var h=fft.hrw;if(h.init&&Math.min(h.nbins,fft.integ_w<<fft.hrw_zoom_i)!=h.draw_w){h.init=false;fft_clear();}else{fft_hrw_apply_zoom();fft_hrw_scale();fft_hrw_status();}}
function fft_recv(data_raw){var firstChars=arrayBufferToStringLen(data_raw,3);if(firstChars=="DAT"){var ba=new Uint8Array(data_raw,4);var cmd=ba[0];var o=1;var len=ba.length-1;var bin=ba[o];o++;len--;if(cmd==fft.cmd_e.FFT){if(spec.source==spec.AUDIO){var data=new Uint8Array(data_raw,6);spectrum_update(data);}else{if(!fft.integ_draw)return;var fc,c,im;if(fft.func==fft.func_e.WF){fc=fft.wf_canvas;c=fc.ctx;im=fc.im;}else{c=fft.integ_canvas.ctx;im=fft.integ_canvas.im;bin-=fft.integ_bino;if(bin<0)
bin+=fft.integ_bins;}
for(var x=0;x<fft.integ_w;x++){var color=waterfall_color_index_max_min(ba[x+o],fft.maxdb,fft.mindb);im.data[x*4+0]=color_map_r[color];im.data[x*4+1]=color_map_g[color];im.data[x*4+2]=color_map_b[color];im.data[x*4+3]=0xff;}
if(fft.func==fft.func_e.WF){c.putImageData(im,0,fft.actual_line);fft.actual_line--;fft.wf1_canvas.style.top=px(fft.wf1_canvas.top++);fft.wf2_canvas.style.top=px(fft.wf2_canvas.top++);if(fft.actual_line<0){var h=fft.integ_h;fft.wf_canvas_i^=1;fft.wf_canvas=fft.wf_canvas_i?fft.wf2_canvas:fft.wf1_canvas;fc=fft.wf_canvas;fc.top=-h+1+fft.integ_hdr;fc.style.top=px(fc.top);fft.actual_line=h-1;}}else{for(var y=0;y<fft.integ_dbl;y++){c.putImageData(im,0,fft.integ_yo+(bin*fft.integ_dbl+y));}}}}else
if(cmd==fft.cmd_e.CLEAR){fft_clear();}else{console.log('fft_recv: DATA UNKNOWN cmd='+cmd+' len='+len);}
return;}
var stringData=arrayBufferToString(data_raw);var params=stringData.substring(4).split(" ");for(var i=0;i<params.length;i++){var param=params[i].split("=");if(0&&param[0]!="keepalive"){if(isDefined(param[1]))
console.log('fft_recv: '+param[0]+'='+param[1]);else
console.log('fft_recv: '+param[0]);}
switch(param[0]){case"ready":fft_controls_setup();break;case"bins":fft.integ_bins=parseInt(param[1]);fft.integ_bino=0;fft.integ_dbl=Math.floor(fft.integ_h / fft.integ_bins);if(fft.integ_dbl<1)fft.integ_dbl=1;fft.integ_yo=(fft.integ_h-fft.integ_dbl*fft.integ_bins)/ 2;if(fft.integ_yo<0)fft.integ_yo=0;fft.integ_yo+=fft.integ_hdr;fft.integ_draw=true;break;default:console.log('fft_recv: UNKNOWN CMD '+param[0]);break;}}}
function fft_controls_setup(){var data_html=time_display_html('fft')+
w3_div('id-fft-data|left:150px; width:1024px; height:200px; background-color:mediumBlue; position:relative; overflow:hidden;','<canvas id="id-fft-wf1-canvas" width="1024" height="188" style="position:absolute"></canvas>','<canvas id="id-fft-wf2-canvas" width="1024" height="188" style="position:absolute"></canvas>','<canvas id="id-fft-integ-canvas" width="1024" height="200" style="position:absolute"></canvas>',w3_div('id-fft-hrw-tt w3-hide|position:absolute; z-index:2; padding:1px 4px; background-color:black; color:white; font-family:Verdana; font-size:10px; pointer-events:none;',''));var info_html=w3_div('id-fft-info|left:0px; height:280px; overflow:hidden; position:relative;','<canvas id="id-fft-info-canvas" width="256" height="280" style="position:absolute"></canvas>');var p=ext_param();if(p){p=p.split(',');p.forEach(function(a,i){console.log('FFT param <'+a+'>');w3_ext_param_array_match_str(fft.func_s,a,function(i){fft.func=i;});w3_ext_param_array_match_str(fft.pre_s,a,function(i){fft.pre=i;});var r;if((r=w3_ext_param('itime',a)).match){fft.itime=w3_clamp(r.num,1,60);}else
if((r=w3_ext_param('maxdb',a)).match){fft.maxdb=w3_clamp(r.num,-170,-10);}else
if((r=w3_ext_param('mindb',a)).match){fft.mindb=w3_clamp(r.num,-190,-30);}else
if((r=w3_ext_param('size',a)).match){var sznum=(r.num<=16)?(r.num*1024):r.num;var best=0;fft.hrw_size_v.forEach(function(sz,i){if(Math.abs(sz-sznum)<Math.abs(fft.hrw_size_v[best]-sznum))best=i;});fft.hrw_size_i=best;}else
if((r=w3_ext_param('overlap',a)).match){var oi=fft.hrw_overlap_v.indexOf(r.num);if(oi!=-1)fft.hrw_overlap_i=oi;}else
if((r=w3_ext_param('decim',a)).match){var di=fft.hrw_decim_v.indexOf(r.num);if(di!=-1)fft.hrw_decim_i=di;}else
if((r=w3_ext_param('zoom',a)).match){var zf=w3_clamp(r.num,1,16);fft.hrw_zoom_i=Math.round(Math.log(zf)/ Math.LN2);}else
if(w3_ext_param('help',a).match){ext_help_click(true);}});}
var controls_html=w3_div('id-fft-controls w3-text-white',w3_half('','0:id-fft-controls-left 1:id-fft-controls-right',info_html,w3_divs('',w3_div('w3-medium w3-text-aqua','<b>Audio FFT</b>'),w3_inline('w3-margin-T-8 w3-halign-space-between w3-valign-end/',w3_select('w3-text-red','Function','','fft.func',fft.func,fft.func_s,'fft_func_cb'),w3_input('w3-width-64 w3-padding-smaller','Integrate<br>time','fft.itime',fft.itime,'fft_itime_cb'),w3_button('w3-margin-T-8 w3-padding-small w3-css-yellow','Clear','fft_clear_cb')),w3_inline('w3-margin-T-8 w3-halign-space-between w3-valign-end/',w3_select('//w3-text-red w3-width-auto','Integrate presets','select','fft.pre',W3_SELECT_SHOW_TITLE,fft.pre_s,'fft_pre_select_cb'),w3_button('w3-padding-small w3-aqua','Auto scale','fft_hrw_autoscale_cb')),w3_div('id-fft-hrw w3-margin-T-8',w3_inline('w3-halign-space-between/',w3_select('w3-text-red','FFT','','fft.hrw_size_i',fft.hrw_size_i,fft.hrw_size_s,'fft_hrw_size_cb'),w3_select('w3-text-red','Overlap','','fft.hrw_overlap_i',fft.hrw_overlap_i,fft.hrw_overlap_s,'fft_hrw_overlap_cb'),w3_select('w3-text-red','Decim','','fft.hrw_decim_i',fft.hrw_decim_i,fft.hrw_decim_s,'fft_hrw_decim_cb'),w3_select('w3-text-red','Zoom','','fft.hrw_zoom_i',fft.hrw_zoom_i,fft.hrw_zoom_s,'fft_hrw_zoom_cb')),w3_inline('w3-margin-T-4 w3-halign-space-between/',w3_div('id-fft-hrw-status w3-margin-T-2 w3-font-11px',''))),w3_div('id-fft-msg-fft w3-margin-T-8',w3_slider('','max','fft.maxdb',fft.maxdb,-170,-10,1,'fft_maxdb_cb'),w3_slider('','min','fft.mindb',fft.mindb,-190,-30,1,'fft_mindb_cb')),w3_text('id-fft-msg-spec  w3-margin-T-8 w3-hide','Spectrum uses main control panel<br>WF tab sliders and settings'))));ext_panel_show(controls_html,data_html,null);fft.saved_mode=ext_get_mode();time_display_setup('fft');fft.integ_canvas=w3_el('id-fft-integ-canvas');fft.integ_canvas.ctx=fft.integ_canvas.getContext("2d");fft.integ_canvas.im=fft.integ_canvas.ctx.createImageData(fft.integ_w,1);fft.integ_canvas.addEventListener("mousedown",fft_mousedown,w3.BUBBLING);fft.integ_canvas.addEventListener("mousemove",fft_hrw_tooltip,w3.BUBBLING);fft.integ_canvas.addEventListener("mouseleave",fft_hrw_tooltip_leave,w3.BUBBLING);fft.wf1_canvas=w3_el('id-fft-wf1-canvas');fft.wf1_canvas.ctx=fft.wf1_canvas.getContext("2d");fft.wf1_canvas.im=fft.wf1_canvas.ctx.createImageData(fft.integ_w,1);fft.wf2_canvas=w3_el('id-fft-wf2-canvas');fft.wf2_canvas.ctx=fft.wf2_canvas.getContext("2d");fft.wf2_canvas.im=fft.wf2_canvas.ctx.createImageData(fft.integ_w,1);fft.info_canvas=w3_el('id-fft-info-canvas');fft.info_canvas.ctx=fft.info_canvas.getContext("2d");fft.hrw.init=false;ext_register_audio_data_cb(fft_audio_data_cb);FFT_environment_changed({resize:1});fft_itime_cb('fft.itime',fft.itime);fft_clear();fft.update_interval=setInterval(fft_update,1000);fft_func_cb('fft.func',fft.func,false);if(fft.pre!=-1)fft_pre_select_cb('fft.pre',fft.pre,false);if(fft.func==fft.func_e.WF){ext_set_mode('iq');fft.passband_mode_altered=true;}}
function FFT_environment_changed(changed){if(changed.mode){ext_send('SET run='+fft.run[fft.func+1]);if(fft.func==fft.func_e.WF)fft_hrw_scale();}
if(changed.passband&&fft.func==fft.func_e.WF&&fft.hrw_decim_v[fft.hrw_decim_i]>1&&!ext_is_IQ_or_stereo_curmode()){fft.hrw.init=false;fft_clear();}
if(changed.resize){var el=w3_el('id-fft-data');var left=(window.innerWidth-fft.integ_w-time_display_width())/ 2;el.style.left=px(left);}}
function fft_alpha(){var c=fft.info_canvas.ctx;var xo=64,xi=48,y=16,yh=20,yi=24,barw=9,nbarw=5;var station,freq;c.font='12px Verdana';var ty=yh/2+10/2;for(freq=0;freq<4;freq++){c.fillStyle='white';var txt,tx;txt=fft.alpha_sched[0][freq];tx=barw/2-c.measureText(txt).width/2;c.fillText(txt,xo+xi*freq+tx,10);txt=fft.alpha_sched[1][freq].toFixed(2);tx=barw/2-c.measureText(txt).width/2;c.fillText(txt,xo+xi*freq+tx,26);y=32;for(var tslot=1;tslot<=6;tslot++){if(freq==0){c.fillStyle='white';c.fillText('slot '+tslot,16,y+ty);}
station=fft.alpha_sched[tslot+2][freq];if(station==fft_a.MULT){c.fillStyle=fft.alpha_station_colors[fft_a.NOVO-1];c.fillRect(xo+xi*freq+(2-2-nbarw),y,nbarw,yh);c.fillStyle=fft.alpha_station_colors[fft_a.REVD-1];c.fillRect(xo+xi*freq+2,y,nbarw,yh);c.fillStyle=fft.alpha_station_colors[fft_a.SEYD-1];c.fillRect(xo+xi*freq+(2+nbarw+2),y,nbarw,yh);}else
if(station){c.fillStyle=fft.alpha_station_colors[station-1];c.fillRect(xo+xi*freq,y,barw,yh);}
y+=yi;}}
y=192;c.font='12px Verdana';for(station=0;station<=4;station++){c.fillStyle=fft.alpha_station_colors[station];c.fillRect(xo,y,yh,barw);c.fillStyle='white';c.fillText(fft.alpha_stations[station],xo+yh+4,y+barw);y+=16;}
c=fft.integ_canvas.ctx;var pxphz=fft.integ_w / ext_sample_rate();c.font='12px Verdana';c.fillStyle='white';for(freq=0;freq<4;freq++){var f_s=fft.alpha_sched[1][freq].toFixed(2);var f=parseFloat(f_s)*1e3;fft_marker(f_s,fft.alpha_sched[2][freq],f);}}
function fft_itime_cb(path,val){var itime=parseFloat(val);if(itime<1)itime=1;itime=itime.toFixed(3);w3_num_cb(path,itime);ext_send('SET itime='+itime);fft_clear();}
function fft_set_itime(itime){w3_set_value('fft.itime',itime);fft_itime_cb('fft.itime',itime);}
function fft_func_cb(path,idx,first){console.log('fft_func_cb new='+idx+' prev='+fft.func+' first='+first);if(first)return;idx=+idx;switch(idx){case fft.func_e.SPEC:w3_hide('id-ext-data-container');ext_show_spectrum(spec.RF);break;default:if(fft.func!=fft.func_e.SPEC)break;ext_hide_spectrum();w3_show_block('id-ext-data-container');break;}
w3_select_value(path,idx);fft.func=idx;w3_show_hide('id-fft-msg-fft',fft.func!=fft.func_e.SPEC);w3_show_hide('id-fft-msg-spec',fft.func==fft.func_e.SPEC);w3_show_hide('id-fft-hrw',fft.func==fft.func_e.WF);if(fft.func==fft.func_e.WF){fft.hrw.init=false;}else{[fft.wf1_canvas,fft.wf2_canvas].forEach(function(cv){if(!cv)return;if(cv.width!=fft.integ_w){cv.width=fft.integ_w;cv.im=cv.ctx.createImageData(fft.integ_w,1);}
cv.style.width='';cv.style.height='';cv.style.left='';});}
fft_clear();w3_attribute(fft.integ_canvas,'title','click to align vertically',fft.func==fft.func_e.INTEG);}
function fft_pre_select_cb(path,idx,first){if(first)return;idx=+idx;fft.integ_draw=false;fft.pre=idx;var func=fft.func_e.INTEG;switch(fft.pre){case fft.pre_none:fft_set_itime(10.0);break;case fft.pre_ALPHA:ext_tune(11.5,'usb',ext_zoom.NOM_IN);ext_set_passband(300,3470);fft.passband_mode_altered=true;fft_set_itime(3.6);break;case fft.pre_JJY40:ext_tune(40,'cw',ext_zoom.NOM_IN);fft_set_itime(1.0);break;case fft.pre_RTZ:ext_tune(50.32,'cwn',ext_zoom.NOM_IN);fft_set_itime(1.0);break;case fft.pre_WWVB_MSF_JJY60:ext_tune(60,'cw',ext_zoom.NOM_IN);fft_set_itime(1.0);break;case fft.pre_RBU:ext_tune(66.35,'cwn',ext_zoom.NOM_IN);fft_set_itime(1.0);break;case fft.pre_BPC:ext_tune(68.5,'cw',ext_zoom.NOM_IN);fft_set_itime(1.0);break;case fft.pre_DCF77:ext_tune(77.5,'cw',ext_zoom.NOM_IN);fft_set_itime(1.0);break;default:func=fft.func_e.SPEC;break;}
w3_select_value(path,idx);fft_func_cb('fft.func',func,false);}
function fft_maxdb_cb(path,val,complete,first){fft.maxdb=parseFloat(val);w3_num_cb(path,val);w3_set_label('WF/integrate max '+val+' dB',path);}
function fft_mindb_cb(path,val,complete,first){fft.mindb=parseFloat(val);w3_num_cb(path,val);w3_set_label('WF/integrate min '+val+' dB',path);}
function fft_clear_cb(path,val){fft_clear();setTimeout(function(){w3_radio_unhighlight(path);},w3_highlight_time);}
function FFT_blur(){console.log('FFT_blur');kiwi_clearInterval(fft.update_interval);ext_unregister_audio_data_cb();ext_send('SET run='+fft.func_e.OFF);spec.need_clear_avg=true;if(fft.passband_mode_altered)
ext_set_mode(fft.saved_mode);}
function FFT_config_html(){ext_config_html(fft,'fft','FFT','FFT configuration');}
function FFT_help(show){if(show){var s=w3_text('w3-medium w3-bold w3-text-aqua','Audio FFT help')+
w3_div('w3-margin-T-8 w3-scroll-y|height:90%',w3_div('w3-margin-R-8','Remember that on KiwiSDR the audio and waterfall channels are completely separate. '+'For example you can pan the waterfall frequency without effecting the audio. '+'By contrast this extension allows visualization of the <i>audio</i> channel itself by using '+'an FFT, waterfall and integrator (summing waterfall) for weak signals.'+'<br><br>The waterfall function computes its FFT in the browser directly from the audio '+'sample stream. The FFT size (hence frequency resolution), FFT overlap (time resolution) '+'and display zoom are selectable. Use IQ mode for the full bandwidth centered on the '+'tuned frequency and the best resolution (IQ audio is never compressed). '+'When there are more FFT bins than display pixels each pixel shows the strongest bin '+'(so narrow carriers are never lost); increase the zoom to see the full resolution. '+'A frequency scale is drawn above the waterfall and hovering the mouse shows '+'frequency and level. The <i>Auto scale</i> button sets the max/min sliders from '+'the current signal statistics.'+'<br><br>The <i>Decim</i> menu decimates the sample stream ahead of the FFT (zoom FFT): '+'the displayed span shrinks by the decimation factor and the resolution improves by '+'the same factor without a larger FFT. E.g. IQ mode, FFT 16k, decim 32: span 375 Hz '+'centered on the tuned frequency at 0.023 Hz/bin &mdash; sub-Hz MW carrier work. '+'In IQ mode the span is centered on the tuned frequency. In USB/LSB/CW modes it is '+'centered on the <i>passband center</i>: drag the passband (or use a /pb URL suffix) '+'to steer the zoomed span. Note the waterfall rate slows accordingly at high '+'decimation and large FFT sizes (see the lines/s readout); use overlap to compensate.'+'<br><br>URL parameters: <br>'+
w3_text('|color:orange','itime:<i>num</i> &nbsp; maxdb:<i>num</i> &nbsp; mindb:<i>num</i> &nbsp; '+'size:<i>num</i> &nbsp; overlap:<i>num</i> &nbsp; decim:<i>num</i> &nbsp; zoom:<i>num</i>')+'<br> Non-numeric values are those appearing in their respective menus. <br>'+'Keywords are case-insensitive and can be abbreviated. <br>'+'So for example these are valid: <br>'+'<i>ext=fft,integ,itime:5</i> &nbsp;&nbsp; '+'<i>ext=fft,water,min:-130,max:-40,size:16,overlap:4</i> &nbsp;&nbsp; <i>ext=fft,alpha</i> <br>'+'(<i>size</i> values &le; 16 mean k units, e.g. size:16 = 16384) <br>'+'<br>'+'Clicking on integrate display will restart it such that the click-point is '+'moved to top of the display (i.e. vertical timing can be realigned).'));confirmation_show_content(s,610,350);w3_el('id-confirmation-container').style.height='100%';}
return true;}



